import { projects } from '../data/projects.js';
import { sectionLabel, arrow, placeholder } from './shared.js';
export function projectArtwork(p) {
  const inside = p.visual === 'orbit' ? '<div class="orbit-sphere"></div><div class="orbit-ring ring-one"></div><div class="orbit-ring ring-two"></div><span class="orbit-point"></span>' : p.visual === 'terrain' ? '<svg class="terrain-lines" viewBox="0 0 700 450" fill="none" aria-hidden="true">'+Array.from({length:19},(_,i)=>`<path d="M-60 ${175+i*16} C100 ${-60+i*10} 175 ${450+i*8} 350 ${170+i*13} S560 ${120+i*14} 780 ${270+i*14}" stroke="currentColor" stroke-width=".8"/>`).join('')+'</svg>' : '<div class="signal-halo"></div><div class="signal-core"></div><div class="signal-line"></div>';
  return `<div class="project-art art-${p.visual}" role="img" aria-label="${p.coverLabel.toLowerCase()} — abstract placeholder cover"><span class="cover-corner">${p.number} / CONCEPT VISUAL</span>${inside}<span class="cover-title">${p.coverLabel}</span><span class="cover-plus">+</span></div>`;
}
export function Projects() { return `<section id="projects" class="section projects container" aria-labelledby="projects-title">${sectionLabel('03','PROJECTS')}<div class="section-heading reveal"><h2 id="projects-title">Selected <span class="soft-text">work.</span></h2><div class="heading-aside"><p>A few spaces for things to come.</p>${placeholder('3 PROJECT PLACEHOLDERS')}</div></div><div class="projects-grid">${projects.map(p=>`<article class="project-card reveal"><a href="#/projects/${p.id}" class="project-link" aria-label="View ${p.title} placeholder">${projectArtwork(p)}<div class="project-info"><div class="project-meta"><span>${p.category}</span><span>${p.year}</span></div><div class="project-title-row"><h3>${p.title}</h3><span class="round-arrow">${arrow}</span></div><p>${p.description}</p><span class="view-project">VIEW PROJECT <span>↗</span></span></div></a></article>`).join('')}</div><div class="section-footnote"><span>AN OPEN CANVAS FOR WHAT COMES NEXT.</span><span>PROJECT DETAILS TO BE ADDED</span></div></section>`; }
